// Parse extracted customer data safely
const data = JSON.parse($node["Customer & Vehicle Details Extractor"].json["output"] || '{}');

const name = data.name?.trim();
const email = data.email?.trim();
const phone = data.phone?.trim();

// Utility function to check if a value is valid
const isValid = (value) => {
  return typeof value === 'string' && value.trim() !== '' && value.trim().toUpperCase() !== 'NA';
};

// Determine update_lead if name or phone is valid
const update_lead = Boolean(isValid(name) || isValid(phone));

// Create lead if valid phone or (no phone but valid email)
const phone_valid = isValid(phone);
let create_lead = phone_valid || (!phone_valid && isValid(email));

// Check communication preference and override create_lead if needed
let preferred_mode = null;
try {
  const commPref = JSON.parse($node["Communication Preference Detection"].json["output"] || '{}');
  preferred_mode = commPref.preferred_mode?.trim().toLowerCase();

  if (preferred_mode === 'sms') {
    create_lead = false; // Override if SMS is preferred
  }
} catch (error) {
  // Fail silently; preferred_mode stays null
  preferred_mode = null;
}

// Send SMS only if create_lead is true and phone is valid
const send_sms = create_lead && phone_valid;

// Final output
return {
  update_lead,
  create_lead,
  send_sms,
  preferred_mode // optional: for debugging/logging
};

